Write a similarity statement with corresponding vertices in matching order. State the test and give full reasoning.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (A) at (0,0);\coordinate (B) at (3,0);\coordinate (C) at (1.5,2.598);
\draw (A)--(B)--(C)--cycle;
\node[below left] at (A) {$A$};\node[below right] at (B) {$B$};\node[above] at (C) {$C$};
\node at (.65,.35) {$60^\circ$};\node at (2.35,.35) {$60^\circ$};
\coordinate (E) at (4.5,0);\coordinate (F) at (8.1,0);\coordinate (D) at (6.3,3.118);
\draw (E)--(F)--(D)--cycle;
\node[below left] at (E) {$E$};\node[below right] at (F) {$F$};\node[above] at (D) {$D$};
\node at (5.15,.35) {$60^\circ$};\node at (7.45,.35) {$60^\circ$};
\end{tikzpicture}
[/tikz]

Two of these three triangles are similar. Choose the pair, state the test and write a similarity statement.

In $\triangle ABC$, $AB=AC=9$ and $BC=4$.
In $\triangle DEF$, $DE=DF=3.6$ and $EF=1.7$.
In $\triangle GHI$, $GH=GI=13.5$ and $HI=6$.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (B) at (0,0);\coordinate (C) at (1.2,0);\coordinate (A) at (.6,2.632);
\draw (A)--(B)--(C)--cycle;
\node[above] at (A) {$A$};\node[below left] at (B) {$B$};\node[below right] at (C) {$C$};
\node[left] at (.3,1.316) {$9$};\node[right] at (.9,1.316) {$9$};\node[below] at (.6,0) {$4$};
\coordinate (E) at (3,0);\coordinate (F) at (3.85,0);\coordinate (D) at (3.425,1.749);
\draw (D)--(E)--(F)--cycle;
\node[above] at (D) {$D$};\node[below left] at (E) {$E$};\node[below right] at (F) {$F$};
\node[left] at (3.2125,.8745) {$3.6$};\node[right] at (3.6375,.8745) {$3.6$};\node[below] at (3.425,0) {$1.7$};
\coordinate (H) at (5.7,0);\coordinate (I) at (7.2,0);\coordinate (G) at (6.45,3.291);
\draw (G)--(H)--(I)--cycle;
\node[above] at (G) {$G$};\node[below left] at (H) {$H$};\node[below right] at (I) {$I$};
\node[left] at (6.075,1.6455) {$13.5$};\node[right] at (6.825,1.6455) {$13.5$};\node[below] at (6.45,0) {$6$};
\end{tikzpicture}
[/tikz]

Show that the triangles are similar. State the test, write a similarity statement and find the scale factor from $\triangle ABC$ to $\triangle DEF$.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (B) at (0,0);\coordinate (A) at (2,0);\coordinate (C) at (1.5,2.598);
\draw (B)--(A)--(C)--cycle;
\node[below left] at (B) {$B$};\node[below right] at (A) {$A$};\node[above] at (C) {$C$};
\node[below] at (1,0) {$6$};\node[left] at (.75,1.299) {$9$};\node at (.7,.4) {$60^\circ$};
\coordinate (E) at (4,0);\coordinate (D) at (7,0);\coordinate (F) at (6.25,3.897);
\draw (E)--(D)--(F)--cycle;
\node[below left] at (E) {$E$};\node[below right] at (D) {$D$};\node[above] at (F) {$F$};
\node[below] at (5.5,0) {$9$};\node[left] at (5.125,1.9485) {$13.5$};\node at (4.7,.4) {$60^\circ$};
\end{tikzpicture}
[/tikz]

Identify the hypotenuses, then show that the triangles are similar. State the test and give full reasoning.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (B) at (0,0);\coordinate (A) at (0,2.4);\coordinate (C) at (1.8,0);
\draw (A)--(B)--(C)--cycle;\draw (0,.22)--(.22,.22)--(.22,0);
\node[above] at (A) {$A$};\node[below left] at (B) {$B$};\node[below right] at (C) {$C$};
\node[left] at (0,1.2) {$8$};\node[above right] at (.9,1.2) {$10$};
\coordinate (E) at (4,0);\coordinate (D) at (4,3.6);\coordinate (F) at (6.7,0);
\draw (D)--(E)--(F)--cycle;\draw (4,.22)--(4.22,.22)--(4.22,0);
\node[above] at (D) {$D$};\node[below left] at (E) {$E$};\node[below right] at (F) {$F$};
\node[left] at (4,1.8) {$12$};\node[above right] at (5.35,1.8) {$15$};
\end{tikzpicture}
[/tikz]

Both triangles are isosceles, with their equal sides marked. Use the angle sum to decide whether they are similar. Give full reasoning.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (B) at (0,0);\coordinate (C) at (3,0);\coordinate (A) at (1.5,.866);
\draw (A)--(B)--(C)--cycle;
\draw (.70,.52)--(.80,.346);\draw (2.20,.346)--(2.30,.52);
\node[above] at (A) {$A$};\node[below left] at (B) {$B$};\node[below right] at (C) {$C$};\node at (1.5,.55) {$120^\circ$};
\coordinate (E) at (4.5,0);\coordinate (F) at (8.1,0);\coordinate (D) at (6.3,1.039);
\draw (D)--(E)--(F)--cycle;
\draw (5.35,.606)--(5.45,.433);\draw (7.15,.433)--(7.25,.606);
\node[above] at (D) {$D$};\node[below left] at (E) {$E$};\node[below right] at (F) {$F$};\node at (5.25,.19) {$30^\circ$};
\end{tikzpicture}
[/tikz]
